import{_ as t,o as s,c as a,a2 as i}from"./chunks/framework.BXzK3EA4.js";const o="/assets/13eba86b4138b983.CMfM1ngH.png",n="/assets/04aa5cc5bc4a964c.CIzBgfwP.png",k=JSON.parse('{"title":"Checking the health status of dedicated server disks","description":"","frontmatter":{"title":"Checking the health status of dedicated server disks"},"headers":[],"relativePath":"operations-knowledge-base/dedicated-server/checking-the-health-status-of-dedicated-server-disks.md","filePath":"operations-knowledge-base/dedicated-server/checking-the-health-status-of-dedicated-server-disks.md","lastUpdated":1794292919000}'),d={name:"operations-knowledge-base/dedicated-server/checking-the-health-status-of-dedicated-server-disks.md"};function r(c,e,l,p,h,u){return s(),a("div",null,[...e[0]||(e[0]=[i('<p>For Windows systems:</p><p>The Windows operating system comes with a built-in disk checking and repair tool called &quot;Check Disk.&quot; It can scan and attempt to fix errors, bad sectors, and other issues in the file system.</p><p>Here are the steps to use the disk check tool:</p><ol><li><p>Open File Explorer (shortcut: Win + E).</p></li><li><p>Select the disk you want to check, right-click on it, and choose &quot;Properties.&quot;</p></li></ol><p><img src="'+o+'" alt=""></p><p>3.In the Properties window, go to the &quot;Tools&quot; tab.</p><p><img src="'+n+'" alt=""></p><ol start="4"><li><p>If the disk is currently in use, you will see a prompt asking if you want to schedule the disk check for the next system restart. If you want to check immediately, click on the &quot;Scan drive&quot; or &quot;Check now&quot; button. Otherwise, select &quot;Schedule disk check&quot; and choose the appropriate option.</p></li><li><p>The system will start scanning and repairing issues on the disk. Once completed, the scan results will be displayed.</p></li></ol><p>In addition to the built-in disk check tool, there are also third-party disk diagnostic software available, such as CrystalDiskInfo, HD Tune, Victoria, and more. These software tools offer more advanced features and can provide additional disk status information and diagnostic reports.</p><p>Linux systems</p><p>In Linux, you can use command-line tools to check the disk health.</p><p>smartmontools: This is a command-line toolset that includes smartctl and smartd. smartctl can check the SMART attributes of the hard disk and report any issues, while smartd can run in the background and monitor the disk status.</p><p>For CentOS:</p><p>yum -y install smartmontools &amp;&amp; smartctl --all /dev/nvme0n1 # Replace /dev/nvme0n1 with the specific device name, which you can find by running sudo fdisk -l.</p><p>For Ubuntu:</p><p>sudo apt install smartmontools &amp;&amp; sudo smartctl --all /dev/nvme0n1 # Replace /dev/nvme0n1 with the specific device name, which you can find by running sudo fdisk -l.</p>',16)])])}const f=t(d,[["render",r]]);export{k as __pageData,f as default};
